// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human edits drafts"
// Changes: In a draft view, export naming and simulation inputs belong to the project – a short note next to those
//          fields says edits are saved to the project. The editor provides whether a draft is shown.

import { createContext, useContext, type ReactNode } from 'react'

const InDraftContext = createContext(false)

export function InDraftProvider({ value, children }: { value: boolean; children: ReactNode }) {
  return <InDraftContext value={value}>{children}</InDraftContext>
}

/** Rendered only in a draft view; give it an id and reference it from the field's aria-describedby. */
export function ProjectSettingNote({ id, what }: { id?: string; what: string }) {
  if (!useContext(InDraftContext)) return null
  return (
    <span id={id} className="mt-1 block text-xs text-amber-200">
      <span aria-hidden="true">↗ </span>
      {what} patrí projektu – zmena sa uloží do projektu, nie do návrhu.
    </span>
  )
}
